#!/usr/bin/env python3
from collections import Counter
import binascii

def read_hex_file(filename):
    with open(filename, 'rb') as f:
        data = f.read()
    return data

def analyze_frequencies(data):
    # Count frequency of each byte
    freq = Counter(data)
    print("\nByte Frequency Analysis:")
    for byte, count in sorted(freq.items(), key=lambda x: x[1], reverse=True)[:20]:
        print(f"0x{byte:02x}: {count} times ({count/len(data)*100:.2f}%)")

def find_repeating_sequences(data, min_len=3, max_len=8):
    print("\nRepeating Sequences Analysis:")
    sequences = {}

    for length in range(min_len, max_len + 1):
        for i in range(len(data) - length):
            seq = data[i:i+length]
            if seq in data[i+1:]:
                sequences[seq] = data.count(seq)

    for seq, count in sorted(sequences.items(), key=lambda x: x[1], reverse=True)[:10]:
        print(f"Sequence {binascii.hexlify(seq)}: appears {count} times")

def analyze_ascii_strings(data):
    print("\nPrintable ASCII Strings:")
    current_string = ""
    for byte in data:
        if 32 <= byte <= 126:
            current_string += chr(byte)
        else:
            if len(current_string) >= 4:
                print(current_string)
            current_string = ""
    if len(current_string) >= 4:
        print(current_string)

def analyze_specific_values(data):
    print("\nAnalysis of specific values (04, 86, a6):")
    print(f"0x04 appears {data.count(0x04)} times")
    print(f"0x86 appears {data.count(0x86)} times")
    print(f"0xa6 appears {data.count(0xa6)} times")

    # Look for patterns between these values
    patterns = []
    for i in range(len(data)-2):
        if data[i] in [0x04, 0x86, 0xa6]:
            pattern = data[i:i+3]
            patterns.append(pattern)

    print("\nCommon patterns containing these values:")
    pattern_freq = Counter(map(bytes, patterns))
    for pattern, count in pattern_freq.most_common(10):
        print(f"Pattern {binascii.hexlify(pattern)}: appears {count} times")

def analyze_spacing(data, target_bytes=[0x04, 0x86, 0xa6]):
    print("\nSpacing Analysis:")
    for byte in target_bytes:
        positions = [i for i, x in enumerate(data) if x == byte]
        if positions:
            distances = [positions[i+1] - positions[i] for i in range(len(positions)-1)]
            common_distances = Counter(distances)
            print(f"\nFor byte 0x{byte:02x}:")
            print("Most common distances between occurrences:")
            for dist, count in sorted(common_distances.items(), key=lambda x: x[1], reverse=True)[:5]:
                print(f"Distance {dist}: {count} times")

if __name__ == "__main__":
    data = read_hex_file("/home/ctfplayer/ctf_files/hypokrinesthai.txt")
    analyze_frequencies(data)
    find_repeating_sequences(data)
    analyze_ascii_strings(data)
    analyze_specific_values(data)
    analyze_spacing(data)

#!/usr/bin/env python3
from collections import Counter
import binascii
import re

def read_file(filename):
    with open(filename, 'rb') as f:
        return f.read()

def extract_hex_values(data):
    # Extract just the hex values between offset and ASCII representation
    hex_pattern = rb'(?<=  )[0-9a-f ]{48}(?=  \|)'
    matches = re.findall(hex_pattern, data)
    return [bytes.fromhex(match.decode()) for match in matches]

def extract_ascii_column(data):
    # Extract the ASCII representation between pipes
    ascii_pattern = rb'\|(.*?)\|'
    return re.findall(ascii_pattern, data)

def analyze_patterns(hex_data):
    patterns = []
    for line in hex_data:
        for i in range(len(line)-2):
            if line[i:i+3] in [b'\x04\x86\xa6', b'\x86\xa6\x04', b'\xa6\x04\x86']:
                context = line[max(0,i-2):min(len(line),i+5)]
                patterns.append(context)

    if patterns:
        print("\nFound patterns around target sequences:")
        pattern_freq = Counter(patterns)
        for pattern, count in pattern_freq.most_common(10):
            print(f"Pattern {binascii.hexlify(pattern)}: appears {count} times")

def look_for_flag_pattern(data):
    # Try to find potential flag patterns
    # Look for 'csawctf{' in various encodings
    flag_pattern = rb'csawctf\{'
    encoded_patterns = [
        flag_pattern,
        ''.join(hex(ord(c))[2:] for c in 'csawctf{').encode(),
        bytes([c ^ 0x86 for c in b'csawctf{'])  # XOR with common byte
    ]

    for pattern in encoded_patterns:
        positions = [m.start() for m in re.finditer(pattern, data, re.IGNORECASE)]
        if positions:
            print(f"\nPotential flag pattern found at positions: {positions}")
            for pos in positions:
                print(f"Context: {data[pos:pos+20]}")

def main():
    data = read_file('/home/ctfplayer/ctf_files/hypokrinesthai.txt')
    hex_values = extract_hex_values(data)
    ascii_values = extract_ascii_column(data)

    print("Analyzing patterns in hex data...")
    analyze_patterns(hex_values)

    print("\nLooking for possible flag patterns...")
    look_for_flag_pattern(data)

    print("\nAnalyzing ASCII column patterns...")
    ascii_freq = Counter(b''.join(ascii_values))
    print("\nMost common characters in ASCII representation:")
    for char, count in ascii_freq.most_common(10):
        print(f"0x{char:02x} ({chr(char) if 32 <= char <= 126 else '?'}): {count} times")

if __name__ == "__main__":
    main()

