def find_control_sequences(data):
    sequences = []
    control_bytes = [b'\x04', b'\x86', b'\xa6']

    # Find sequences between control bytes
    for i in range(len(data)):
        for ctrl in control_bytes:
            if data[i:i+1] == ctrl:
                # Look for next control byte
                for j in range(i+1, len(data)):
                    if data[j:j+1] in control_bytes:
                        sequences.append({
                            'start_byte': data[i:i+1],
                            'end_byte': data[j:j+1],
                            'sequence': data[i+1:j],
                            'start_pos': i,
                            'end_pos': j
                        })
                        break

    return sequences

def analyze_sequences(sequences):
    print("=== Sequence Analysis ===")
    pattern_map = {}

    for seq in sequences:
        key = (seq['start_byte'], seq['end_byte'])
        if key not in pattern_map:
            pattern_map[key] = []
        pattern_map[key].append(seq['sequence'])

        # Look for printable ASCII
        printable = ''
        for byte in seq['sequence']:
            if chr(byte) in string.printable:
                printable += chr(byte)

        if len(printable) > 3:  # Only show sequences with multiple printable chars
            print(f"\nControl: {seq['start_byte'].hex()} -> {seq['end_byte'].hex()}")
            print(f"Sequence (hex): {seq['sequence'].hex()}")
            print(f"Printable ASCII: {printable}")

            # Try XOR with common values
            for xor_val in [0x13, 0x37, 0x42, 0x55, 0xff]:
                xored = bytes([b ^ xor_val for b in seq['sequence']])
                printable_xor = ''.join(chr(b) if chr(b) in string.printable else '.' for b in xored)
                if 'csawctf{' in printable_xor or any(c.isalpha() for c in printable_xor):
                    print(f"XOR 0x{xor_val:02x}: {printable_xor}")

    return pattern_map

def main():
