    sequences = find_control_sequences(data)
    pattern_map = analyze_sequences(sequences)

    # Look specifically for potential flag format
    print("\n=== Looking for Flag Format Patterns ===")
    flag_pattern = b'csawctf{'
    for i in range(len(data)-len(flag_pattern)):
        window = data[i:i+len(flag_pattern)]
        # Try different XOR values
        for xor_val in range(256):
            xored = bytes([b ^ xor_val for b in window])
            if xored == flag_pattern:
                print(f"Found potential flag marker at offset {i}")
                print(f"XOR value: 0x{xor_val:02x}")
                # Extract more context
                context = data[i:i+50]  # Get more bytes to see full flag
                decoded = bytes([b ^ xor_val for b in context])
                print(f"Decoded context: {decoded}")

