#!/usr/bin/env python3
from pwn import *
import string

def is_printable(text):
    return all(chr(c) in string.printable for c in text)

def extract_sequences(data):
    sequences = []
    i = 0
    while i < len(data):
        if data[i] == 0x86:
            start = i + 1
            # Look for 0xa6 marker
            end = data.find(bytes([0xa6]), start)
            if end != -1:
                sequences.append(data[start:end])
                i = end
            else:
                break
        i += 1
    return sequences

def xor_with_key(data, key):
    return bytes([b ^ key for b in data])

def reverse_and_xor(sequence):
    results = []
    # Try normal sequence
    for key in range(0x80, 0x90):  # 0x80-0x8f
        decoded = xor_with_key(sequence, key)
        if is_printable(decoded):
            results.append(('normal', key, decoded))

    for key in range(0xe0, 0x100):  # 0xe0-0xff
        decoded = xor_with_key(sequence, key)
        if is_printable(decoded):
            results.append(('normal', key, decoded))

    # Try reversed sequence
    rev_sequence = sequence[::-1]
    for key in range(0x80, 0x90):
        decoded = xor_with_key(rev_sequence, key)
        if is_printable(decoded):
            results.append(('reversed', key, decoded))

    for key in range(0xe0, 0x100):
        decoded = xor_with_key(rev_sequence, key)
        if is_printable(decoded):
            results.append(('reversed', key, decoded))

    return results

def main():
    # Read the file
    with open('/home/ctfplayer/ctf_files/hypokrinesthai.txt', 'rb') as f:
        data = f.read()

    sequences = extract_sequences(data)
    print(f"Found {len(sequences)} sequences between 0x86 and 0xa6")

    promising_results = []
    for i, seq in enumerate(sequences):
        results = reverse_and_xor(seq)
        for direction, key, decoded in results:
            decoded_str = decoded.decode('ascii', errors='ignore')
            # Check for promising content
            if ('csawctf{' in decoded_str or 
                all(c in string.printable for c in decoded_str) and 
                any(c in string.ascii_letters for c in decoded_str)):
                promising_results.append({
                    'sequence_num': i,
                    'direction': direction,
                    'key': hex(key),
                    'decoded': decoded_str
                })

    print("\nPromising results:")
    for result in promising_results:
        print(f"\nSequence #{result['sequence_num']}")
        print(f"Direction: {result['direction']}")
        print(f"Key: {result['key']}")
        print(f"Decoded: {result['decoded']}")

if __name__ == '__main__':
    main()

