from pwn import *
import string

def is_flag_char(c):
    return c in string.ascii_letters or c in string.digits or c in '_{}@'

def is_possible_flag(text):
    return all(is_flag_char(chr(c)) for c in text) and len(text) > 5

def extract_sequences(data):
    sequences = []
    i = 0
    while i < len(data):
        if data[i] == 0x86:
            start = i + 1
            end = data.find(bytes([0xa6]), start)
            if end != -1:
                sequences.append(data[start:end])
                i = end
            else:
                break
        i += 1
    return sequences

def xor_with_key(data, key):
    return bytes([b ^ key for b in data])

def try_decode_flag(sequence, direction="normal"):
    results = []
    seq = sequence[::-1] if direction == "reversed" else sequence

    # First try the flag format directly
    if b'csawctf{' in seq:
        results.append(('raw', 0, seq))

    # Try XOR with keys
    for key in range(0x80, 0x90):  # 0x80-0x8f
        decoded = xor_with_key(seq, key)
        if b'csawctf{' in decoded or is_possible_flag(decoded):
            results.append((direction, key, decoded))

    for key in range(0xe0, 0x100):  # 0xe0-0xff
        decoded = xor_with_key(seq, key)
        if b'csawctf{' in decoded or is_possible_flag(decoded):
            results.append((direction, key, decoded))

    return results

def main():
    # Read the file
    with open('/home/ctfplayer/ctf_files/hypokrinesthai.txt', 'rb') as f:
        data = f.read()

    sequences = extract_sequences(data)
    print(f"Found {len(sequences)} sequences between 0x86 and 0xa6")

    promising_results = []
    for i, seq in enumerate(sequences):
        # Try normal direction
        results = try_decode_flag(seq, "normal")
        promising_results.extend([(i, *r) for r in results])

        # Try reversed
        results = try_decode_flag(seq, "reversed")
        promising_results.extend([(i, *r) for r in results])

    print("\nPromising results that could contain flag content:")
    seen = set()
    for seq_num, direction, key, decoded in promising_results:
        try:
            decoded_str = decoded.decode('ascii', errors='ignore')
            if decoded_str not in seen and len(decoded_str.strip()) > 0:
                print(f"\nSequence #{seq_num}")
                print(f"Direction: {direction}")
                print(f"Key: {hex(key) if key else 'none'}")
                print(f"Decoded: {decoded_str}")
                seen.add(decoded_str)
        except:
            continue

